after.content:
if ($LASTEXITCODE -ne 0) { throw "stage 0 regression gate failed: $LASTEXITCODE" }
& node .\scripts\verify-api-baseline.mjs
if ($LASTEXITCODE -ne 0) { throw "API baseline verification failed: $LASTEXITCODE" }
& .\gradlew.bat test --offline --rerun-tasks --no-daemon
if ($LASTEXITCODE -ne 0) { throw "Java tests failed: $LASTEXITCODE" }
& corepack pnpm --offline --filter '@ji/web-app' test
